SELECT date, units_sold FROM store.daily_sales
WHERE sku = 'ATTA-WW-5KG' AND date >= DATE '2026-06-27'
ORDER BY date;

SELECT COUNT(*) AS n_rows, MIN(date) AS min_d, MAX(date) AS max_d
FROM store.daily_sales WHERE sku = 'ATTA-WW-5KG';

SELECT COUNT(*) AS pos_lines_june, SUM(qty) AS qty_sum
FROM store.pos_lines
WHERE sku_scanned = 'ATTA-WW-5KG'
  AND bill_ts >= TIMESTAMP '2026-06-01' AND bill_ts < TIMESTAMP '2026-07-01';

SELECT date, units, reason FROM store.write_offs
WHERE sku = 'ATTA-WW-5KG' AND date >= DATE '2026-06-01' AND date < DATE '2026-07-01'
ORDER BY date;

SELECT count_ts, book_before, counted, adjustment, trigger FROM store.stock_counts
WHERE sku = 'ATTA-WW-5KG' ORDER BY count_ts;

SELECT date, units, reason FROM store.write_offs
WHERE sku = 'ATTA-WW-5KG' AND date >= DATE '2026-06-01' AND date < DATE '2026-07-01'
ORDER BY date;

SELECT DISTINCT audit_ts::date AS d, COUNT(*) OVER () AS total
FROM store.shelf_audits ORDER BY d;

SELECT COUNT(DISTINCT audit_ts::date) AS distinct_days,
       COUNT(DISTINCT audit_ts::time) AS distinct_times
FROM store.shelf_audits;

SELECT note, COUNT(*) FROM payments.pos_payments
WHERE note IS NOT NULL AND note <> '' GROUP BY note;

SELECT COUNT(*) FROM payments.customer_complaints;

SELECT table_schema, table_name FROM information_schema.tables
WHERE table_schema IN ('store','warehouse','payments') AND table_type = 'BASE TABLE'
ORDER BY table_schema, table_name;

SELECT SUM(units_sold) AS total_bags, COUNT(*) AS days_with_data
FROM store.daily_sales
WHERE sku = 'ATTA-WW-5KG' AND date >= DATE '2026-06-01' AND date < DATE '2026-07-01';

SELECT MIN(date) AS min_d, MAX(date) AS max_d, COUNT(DISTINCT date) AS n_days
FROM store.daily_sales;

SELECT date, COUNT(*) AS skus FROM store.daily_sales
WHERE date >= DATE '2026-06-26' GROUP BY date ORDER BY date;
